 void pixel(Bitmap image,double lon,double lat,int expected)throws Exception{int x=(int)Math.round(image.getWidth()/2.0+lon/360*2048),y=(int)Math.round(image.getHeight()/2.0-Math.log(Math.tan(Math.PI/4+Math.toRadians(lat)/2))/(2*Math.PI)*2048);int actual=image.getPixel(x,y);m.check(Math.abs(Color.red(actual)-Color.red(expected))<=1&&Math.abs(Color.green(actual)-Color.green(expected))<=1&&Math.abs(Color.blue(actual)-Color.blue(expected))<=1,"component actual renderer pixel "+lon+","+lat+" expected="+Integer.toHexString(expected)+" actual="+Integer.toHexString(actual));}
 void render(Object doc)throws Exception{final Throwable[] failure={null};m.runOnMainSync(()->{Object map=null;Bitmap image=null;try{Class<?> listener=m.owned("LocalMapView$Listener");Object callback=Proxy.newProxyInstance(listener.getClassLoader(),new Class[]{listener},(o,method,args)->null);map=m.owned("LocalMapView").getConstructor(Context.class,List.class,File.class,listener).newInstance(m.getTargetContext(),m.call(doc,"features",new Class[]{boolean.class},false),null,callback);for(Object feature:(List)m.call(doc,"features",new Class[]{boolean.class},false)){org.w3c.dom.Element e=(org.w3c.dom.Element)feature.getClass().getField("element").get(feature);if("isolated".equals(e.getAttribute("id")))m.check(feature.getClass().getField("color").getInt(feature)==0xffff0000,"fixture demonstrates legacy f.color coupling independently of component defaults");}View view=(View)map;Field paintField=map.getClass().getDeclaredField("paint");paintField.setAccessible(true);m.check(((Paint)paintField.get(map)).getTypeface().equals(m.staticCall("WorkspaceUi","font",new Class[]{Context.class},m.getTargetContext())),"KML labels use approved Arimo typeface");view.layout(0,0,800,600);m.call(map,"restore",new Class[]{double.class,double.class,double.class},.5,.5,3.0);Field ready=map.getClass().getDeclaredField("mapReady");ready.setAccessible(true);ready.setBoolean(map,false);image=Bitmap.createBitmap(800,600,Bitmap.Config.ARGB_8888);view.draw(new Canvas(image));pixel(image,-20,20,0xff00ff00);pixel(image,-10,-10,0xff0000ff);pixel(image,15,-15,0xff921710);pixel(image,-15,7,0xff253020);pixel(image,-25,7,0xff253020);pixel(image,20,20,0xff253020);pixel(image,5,-15,0xff0000ff);pixel(image,-50,20,0xffff0000);pixel(image,-40,-10,0xffe6c45a);pixel(image,-40,-27,0xff595830);}catch(Throwable e){failure[0]=e;}finally{if(image!=null)image.recycle();if(map!=null)try{m.call(map,"close",new Class[]{});}catch(Exception e){failure[0]=e;}}});if(failure[0]!=null)throw new AssertionError(failure[0]);}
 org.w3c.dom.Element definition(Object doc,String tag,String id)throws Exception{org.w3c.dom.Element root=(org.w3c.dom.Element)m.call(doc,"root",new Class[]{}),found=null;org.w3c.dom.NodeList nodes=root.getElementsByTagNameNS("http://www.opengis.net/kml/2.2",tag);int count=0;for(int i=0;i<nodes.getLength();i++){org.w3c.dom.Element candidate=(org.w3c.dom.Element)nodes.item(i);if(id.equals(candidate.getAttribute("id"))){found=candidate;count++;}}m.check(count==1,"exactly one original shared "+tag+" definition with id="+id);return found;}
